namespace Ilmenyx.Desktop;

/// <summary>
/// Shared brushes. They are mutable <see cref="SolidColorBrush"/> instances, so switching the theme recolours every existing control at once.
/// Fg is the "ink" colour (light on dark, dark on light); wherever Fg is a background (inverted chips/badges) the text on it must be OnFg.
/// Glass is a translucent surface (#AARRGGBB) laid over the ambient light, the Apple-style finish of the manual.
/// Each entry is (dark, light). Roles follow Material 3: Bg = surface, Card = surfaceContainer, Accent = primary, and so on.
/// </summary>
public static class Palette
{
    private static readonly (string Dark, string Light)[] Colors =
    [
        ("#181A1C", "#F8F9FD"),
        ("#1E2022", "#F2F4F7"),
        ("#222427", "#ECEEF1"),
        ("#35373B", "#E0E2E6"),
        ("#424750", "#C7CCD6"),
        ("#E6E8EC", "#26282B"),
        ("#BCC1CB", "#4F555F"),
        ("#858C98", "#767C89"),
        ("#A4C1FB", "#255EE9"),
        ("#E7B878", "#8C5D0B"),
        ("#181A1C", "#F8F9FD"),
        ("#A4C1FB", "#255EE9"),
        ("#613F03", "#FEE4C2"),
        ("#052784", "#FFFFFF"),
        ("#1442B5", "#D5E3FE"),
        ("#DEE9FE", "#021F74"),
        ("#88D5A6", "#107C4A"),
        ("#FB9F9A", "#C12C36"),
